```python
def find_path(graph, start, goal):
    stack = [(start, [start])]  # Stack to hold nodes and their corresponding path
    while stack:
        (node, path) = stack.pop()
        for next_node in graph[node] - set(path):
            if next_node == goal:
                return path + [next_node]
            else:
                stack.append((next_node, path + [next_node]))  # Add the next node to the stack with its path
    return None  # Return None if goal is unreachable

# Example graph represented as a dictionary
graph_example = {
    'A': {'B', 'C'},
    'B': {'A', 'D', 'E'},
    'C': {'A', 'F'},
    'D': {'B'},
    'E': {'B', 'F'},
    'F': {'C', 'E'}
}

# Test the function
print(find_path(graph_example, 'A', 'F'))  # Returns: ['A', 'C', 'F']
print(find_path(graph_example, 'A', 'G'))  # Returns: None
```

