from collections import deque

def find_path(graph, start, goal):
    if start == goal:
        return [start]

    # Mark all nodes as not visited
    visited = set()
    # Queue for BFS
    queue = deque([start])

    # Record the path
    path = {start: None}

    while queue:
        node = queue.popleft()
