import heapq

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Priority queue to hold the nodes to be processed
    priority_queue = []
    heapq.heappush(priority_queue, (0, start))
    visited = set()
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_node == goal:
            return reconstruct_path(graph, start, goal, distances)

        if current_node in visited:
            continue

        visited.add(current_node)

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return None

def reconstruct_path(graph, start, goal, distances):
    path = []
    node = goal
    while node != start:
        path.append(node)
        neighbors = graph[node]
        for neighbor, _ in neighbors.items():
            if neighbor == start:
                path.append(neighbor)
                return path[::-1]
            if distances[neighbor] == distances[node] - neighbors[neighbor]:
                node = neighbor
            else:
                break
    path.append(start)
    return path[::-1]

