```python
def find_path(graph, start, goal):
    def dfs(graph, current, goal, path):
        if current == goal:
            return path + [current]
        for neighbor in graph.get(current, []):
            if neighbor not in path:
                new_path = dfs(graph, neighbor, goal, path + [current])
                if new_path:
                    return new_path
        return None

    return dfs(graph, start, goal, [])

