def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Bidirectional Search
    # Initialization
    forward_queue = {start}
    backward_queue = {goal}
    forward_seen = {start}
    backward_seen = {goal}
    parent_forward = {start: None}
    parent_backward = {goal: None}

    # BFS Loop
    while forward_queue and backward_queue:
        if len(forward_queue) > len(backward_queue):
            forward_queue, backward_queue = backward_queue, forward_queue
            parent_forward, parent_backward = parent_backward, parent_forward

        # Get the current node
        current = forward_queue.pop()
        if current in backward_queue:
            # Found a path
            path = []
            while current is not None:
                path.append(current)
                current = parent_forward[current]
            return path[::-1]  # Reverse to get the correct path

        for neighbor in graph[current]:
            if neighbor not in forward_seen:
                forward_queue.add(neighbor)
                parent_forward[neighbor] = current
                forward_seen[neighbor] = True

    return None

