```python
def find_path(graph, start, goal):
    def iterative_deepening_dfs(depth_limit):
        stack = [(start, [start])]
        while stack:
            (node, path) = stack.pop()
            if node == goal:
                return path
            if node not in visited:
                visited.add(node)
                for neighbor in reversed(graph[node]):
                    if depth_limit > 0:
                        stack.append((neighbor, path + [neighbor]))
                    elif depth_limit == 0:
                        return None
        return None

    visited = set()
    for depth_limit in range(1, len(graph) + 2):  # Start from depth 1 to avoid infinite loop
        result = iterative_deepening_dfs(depth_limit)
        if result is not None:
            return result
    return None

# Example usage:
graph = {
    'A': ['B', 'C'],
    'B': ['D', 'E'],
    'C': ['F'],
    'D': [],
    'E': ['F'],
    'F': []
}
start = 'A'
goal = 'F'
print(find_path(graph, start, goal))  # Output: ['A', 'C', 'F']
```

