def find_path(graph, start, goal):
    def ids_search(max_depth):
        # Queue for nodes to be explored
        frontier = [(start, [start])]
        # Set to keep track of nodes already visited
        explored = set()

        while frontier:
            node, path = frontier.pop(0)
            if node in explored:
                continue
            explored.add(node)
            if node == goal:
                return path
            if len(path) <= max_depth:
                for neighbor in graph.get(node, []):
                    if neighbor not in explored:
                        frontier.append((neighbor, path + [neighbor]))
        return None

    # Try increasing depths until a path is found or all depths have been tried
    for depth in range(1, len(graph) + 1):
        result = ids_search(depth)
        if result:
            return result

    return None

