def find_path(graph, start, goal):
    def dfs(graph, node, visited=None):
        if visited is None:
            visited = set()
        if node not in visited:
            visited.add(node)
            if node == goal:
                return True
            for neighbor in graph[node]:
                if dfs(graph, neighbor, visited):
                    return True
        return False

    # Check if start node is not in the graph
    if start not in graph:
        return None

    # Perform DFS from start node
    if dfs(graph, start):
        # Reconstruct the path from visited nodes
        path = [goal]
        while path[-1] != start:
            for neighbor in graph:
                if neighbor in graph[path[-1]] and dfs(graph, neighbor):
                    path.append(neighbor)
                    break
        path.reverse()
        return path
    else:
        return None

