def find_path(graph, start, goal):
    def iter_deepening_dfs(limit):
        stack = [(start, [start])]
        visited = set()
        while stack:
            node, path = stack.pop()
            visited.add(node)
            if node == goal:
                return path
            if len(path) <= limit and node in graph:
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        stack.append((neighbor, path + [neighbor]))
        return None

    # Iterative Deepening DFS
    for depth in range(len(graph) + 1):
        result = iter_deepening_dfs(depth)
        if result:
            return result
    return None
```

