def find_path(graph, start, goal):
    # Initialize the stack for DFS
    stack = [(start, [start])]
    while stack:
        (vertex, path) = stack.pop()
        for next_vertex in graph[vertex]:
            if next_vertex not in path:
                # If the next_vertex is the goal, return the path
                if next_vertex == goal:
                    return path + [next_vertex]
                else:
                    # Otherwise, push the next_vertex onto the stack
                    stack.append((next_vertex, path + [vertex]))
    # If the goal is not reached, return None
    return None
```

