```python
def bfs(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    queue = [(start, [start])]
    visited = set()

    while queue:
        (node, path) = queue.pop(0)
        if node in visited:
            continue
        visited.add(node)

        if node == goal:
            return path

        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))

    return None

def dfs(graph, start, goal, depth=-1):
    if start not in graph or goal not in graph:
        return None

    def depth_limited_search(node, path, max_depth):
        if max_depth == 0:
            return None
        if node == goal:
            return path

        visited = set()
        queue = [(node, path + [node])]

        while queue:
            (node, path) = queue.pop(0)
            if node in visited:
                continue
            visited.add(node)

            for neighbor in graph[node]:
                if neighbor not in visited:
                    new_path = path + [neighbor]
                    if neighbor == goal:
                        return new_path
                    elif depth_limited_search(neighbor, new_path, max_depth - 1):
                        return new_path

        return None

    return depth_limited_search(start, [start], depth)

def iddfs(graph, start, goal):
    for depth in range(0, len(graph)):
        result = dfs(graph, start, goal, depth)
        if result is not None:
            return result
    return None

def find_path(graph, start, goal):
    # First try BFS, if it fails, then try IDDFS
    bfs_path = bfs(graph, start, goal)
    if bfs_path is None:
        depth = len(graph)
        iddfs_path = iddfs(graph, start, goal)
        if iddfs_path is not None:
            return iddfs_path
    return bfs_path

# Example graph
graph = {
    'A': ['B', 'C'],
    'B': ['D', 'E'],
    'C': ['F'],
    'D': [],
    'E': ['F'],
    'F': []
}

# Test the function
