```python
def find_path(graph, start, goal):
    stack = [(start, [start])]  # Stack to keep track of nodes to visit
    visited = set()  # Set to keep track of visited nodes to prevent cycles

    while stack:
        current_node, path = stack.pop()
        if current_node == goal:
            return path  # Found the goal, return the path
        if current_node not in visited:
            visited.add(current_node)
            neighbors = graph.get(current_node, [])
            for neighbor in reversed(neighbors):
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))  # Add neighbors to stack in reverse order
    return None  # Goal is unreachable
```

