from collections import deque

def find_path(graph, start, goal):
    def bidirectional_search(left_frontier, right_frontier, left_visited=None, right_visited=None):
        if left_visited is None:
            left_visited = set()
        if right_visited is None:
            right_visited = set()

        left_queue, right_queue = deque([start]), deque([goal])
        left_parent, right_parent = {start: None}, {goal: None}

        while left_queue and right_queue:
            # Expand nodes from the left side
            for _ in range(len(left_queue)):
                current = left_queue.popleft()
                if current in right_visited:
                    path_from_left = deque()
                    node = current
                    while node is not None:
                        path_from_left.appendleft(node)
                        node = left_parent[node]
                    path_from_right = deque()
                    node = goal
                    while node is not None:
                        path_from_right.appendleft(node)
                        node = right_parent[node]
                    return path_from_left + path_from_right

                if current not in left_visited:
                    left_visited.add(current)
                    for neighbor in graph.get(current, []):
                        if neighbor not in left_visited:
                            left_queue.append(neighbor)
                            left_parent[neighbor] = current

            # Expand nodes from the right side
            for _ in range(len(right_queue)):
                current = right_queue.popleft()
                if current in left_visited:
                    path_from_right = deque()
                    node = current
                    while node is not None:
                        path_from_right.appendleft(node)
                        node = left_parent[node]
                    path_from_left = deque()
                    node = start
                    while node is not None:
                        path_from_left.appendleft(node)
                        node = right_parent[node]
                    return path_from_left + path_from_right

                if current not in right_visited:
                    right_visited.add(current)
                    for neighbor in graph.get(current, []):
                        if neighbor not in right_visited:
                            right_queue.append(neighbor)
                            right_parent[neighbor] = current

        return None

    # Initialize the search
    return bidirectional_search(set(), set(graph.keys()))

