    def dijkstra(parsed_graph, source, target):
        distances = {node: float('inf') for node in parsed_graph}
        distances[source] = 0
        queue = [(0, source)]
        while queue:
            current_distance, current_node = heapq.heappop(queue)

            # Check if we have reached the target
            if current_node == target:
                return current_distance, []

            # If we have already computed a shorter distance to current_node, skip it
            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in parsed_graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

