Certainly! Johnson's algorithm is a well-known method for solving the shortest path problem in a weighted graph, especially when dealing with negative weights. It involves the following steps:

1. **Eliminate Negative Weights**: Use a modification of Dijkstra's algorithm to treat all edge weights as non-negative.
2. **Compute Shortest Paths**: Use the Bellman-Ford algorithm to compute the shortest paths from the source to all other nodes.
3. **Reconstruct the Path**: Use the computed distances to determine the actual shortest path.

Here's the function in Python:

```python
import heapq
from collections import defaultdict

def shortest_path(graph, source, target):
    def bellman_ford(graph, source):
        dist = {node: float('inf') for node in graph}
        dist[source] = 0

        for _ in range(len(graph) - 1):
            for u, neighbors in graph.items():
                for v, weight in neighbors:
                    if dist[u] != float('inf') and dist[u] + weight < dist[v]:
                        dist[v] = dist[u] + weight

        # Check for negative weight cycles
        for u, neighbors in graph.items():
            for v, weight in neighbors:
                if dist[u] != float('inf') and dist[u] + weight < dist[v]:
                    raise ValueError("Graph contains a negative weight cycle")

        return dist

    def dijkstra(graph, source):
        dist = {node: float('inf') for node in graph}
        dist[source] = 0
        queue = [(0, source)]

        while queue:
            current_distance, u = heapq.heappop(queue)

            if current_distance > dist[u]:
                continue

            for neighbor, weight in graph[u]:
                distance = current_distance + weight
                if distance < dist[neighbor]:
                    dist[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return dist

    # Transform the graph to eliminate negative weights
    transformed_graph = defaultdict(lambda: [(target, 0)])
    for node, neighbors in graph.items():
        for neighbor, weight in neighbors:
            transformed_graph[node][0] += weight

    # Compute shortest paths in the transformed graph
    dist = bellman_ford(transformed_graph, source)

    # Reconstruct the path
    path = [source]
    current_node = target
    while current_node != source:
        for neighbor, weight in graph[current_node]:
            if dist[neighbor] == dist[current_node] + weight:
                path.append(neighbor)
                current_node = neighbor
                break

    # If the path is not found, return infinity and None
    if path[-1] != source:
        return float('inf'), None
    else:
        path.reverse()
        return (dist[target], path)

