from heapq import heappush, heappop

def shortest_path(graph, source, target):
    # Helper function to get neighbors with weights
    def get_neighbors(node):
        return [(w, neighbor) for neighbor, w in graph[node] if neighbor != source]

    # Prim's algorithm to find the MST and then compute the shortest path
    def prim_mst(graph, source):
        visited = {source}
        mst = []
        heap = [(0, source)]
        while heap:
            weight, node = heappop(heap)
            if node in visited:
                continue
            visited.add(node)
            mst.append((node, weight))
            for neighbor, w in get_neighbors(node):
                if neighbor not in visited:
                    heappush(heap, (w, neighbor))
        return mst

    # Find the MST and reconstruct the shortest path
    mst = prim_mst(graph, source)
    path = [source]
    current = target
    while current != source:
        for neighbor, weight in mst:
            if neighbor == current:
                path.append(neighbor)
                current = neighbor
                break
    if path[-1] != source:
        path = []
    return (len(path) - 1, path) if path else (float("inf"), None)

