    # Function to check if the target is reachable from the source
    def is_reachable(graph, source, target):
        visited = set()
        queue = deque([(source, 0)])  # (node, dist)
        while queue:
            node, dist = queue.popleft()
            if node == target:
                return True
            if node not in visited:
                visited.add(node)
                for neighbour, weight in graph.get(node, []):
                    queue.append((neighbour, dist + weight))
        return False

    # Function to find the shortest path if exists
    def find_shortest_path(graph, source, target):
        visited = set()
        distances = {node: float('inf') for node in graph}  # Distance from source to node
        distances[source] = 0  # Distance from source to source is 0
        queue = deque([(source, 0)])  # (node, dist)
        while queue:
            node, dist = queue.popleft()
            if node == target:
                return dist
            if node not in visited:
                visited.add(node)
                for neighbour, weight in graph.get(node, []):
                    if distances[node] + weight < distances[neighbour]:
                        distances[neighbour] = distances[node] + weight
                        queue.append((neighbour, distances[neighbour]))
        return float('inf')

    # Check if target is reachable
    if not is_reachable(graph, source, target):
        return float('inf'), None

    # Find the shortest path if target is reachable
    shortest_dist = find_shortest_path(graph, source, target)
    path = [target]
    while target in graph:
        target = min(graph[target], key=lambda x: (distances[x], x))[0]  # Choose the neighbor with the smallest distance
        path.append(target)
    path.reverse()
    return shortest_dist, path

