def shortest_path(graph, source, target):
    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    paths = {node: [] for node in graph}
    distances[source] = 0
    paths[source] = [source]

    # Check if the source and target nodes are the same
    if source == target:
        return (0, [source])

    # Set of all visited nodes to avoid revisiting
    visited = set()

    while target not in visited:
        # Choose the node with the smallest known distance
        current_node = min(distances, key=distances.get)

        # Mark the current node as visited
        visited.add(current_node)

        # Explore all neighbors of the current node
        for neighbor, weight in graph[current_node]:
            if neighbor not in visited:
                distance = distances[current_node] + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    paths[neighbor] = paths[current_node] + [neighbor]

    if target not in visited:
        # If the target node is unreachable, return infinity for the distance and None for the path
        return (float('inf'), None)
    else:
        # Return the shortest distance and the shortest path
        return (distances[target], paths[target])

