def shortest_path(graph, source, target):
    # Initialize the distance matrix with the maximum possible value
    dist = {node: {neighbor: float("inf") for neighbor in graph[node]} for node in graph}

    # Initialize the path matrix with None
    path = {node: {neighbor: None for neighbor in graph[node]} for node in graph}

    # Source to itself has distance 0
    for node in graph:
        dist[node][node] = 0

    # Floyd-Warshall Algorithm
    for k in graph:
        for i in graph:
            for j in graph:
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
                    path[i][j] = path[k][j]

    # Check if the target is reachable from the source
    if dist[source][target] == float("inf"):
        return (float("inf"), None)
    else:
        # Reconstruct the shortest path
        path_list = [target]
        i = target
        while i != source:
            i = path[source][i]
            path_list.append(i)
        path_list.reverse()
        return (dist[source][target], path_list)

