def shortest_path(graph, source, target):
    def dijkstra(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        priority_queue = [(0, source)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            # If the current distance is greater than the recorded distance, skip
            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                # If a shorter path is found, update the record
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

    # Apply Johnson's algorithm
    # 1. Add a new node s' linked to all nodes with 0 weight
    # 2. Run Bellman-Ford from s' to detect negative cycles
    # 3. Transform the original graph
    s_prime = 's_prime'
    graph[s_prime] = {node: 0 for node in graph}

    # 1. Run Bellman-Ford from s' to detect negative cycles
    distances = dijkstra(graph, s_prime)
    for distance in distances.values():
        if distance == float('inf'):
            return (float('inf'), None)

    # 2. Transform the original graph
    for node, edges in graph.items():
        for neighbor, weight in edges:
            graph[node][neighbor] += distances[neighbor] - distances[node]

    # 3. Run Dijkstra from source to target
    distances = dijkstra(graph, source)

    # Check if the target is reachable
    if distances[target] == float('inf'):
        return (float('inf'), None)

    # Reconstruct the path
    path = [target]
    current_node = target
    while current_node != source:
        for neighbor, weight in graph[current_node]:
            if distances[neighbor] == distances[current_node] - weight:
                path.append(neighbor)
                current_node = neighbor
                break

    path.reverse()

    return (distances[target], path)

