def shortest_path(graph, source, target):
    # Create a priority queue to hold (distance, node) pairs
    queue = [(0, source)]

    # Dictionary to keep track of the shortest known distance to each node
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Dictionary to keep track of the previous node on the lowest-cost path to each node
    previous = {node: None for node in graph}

