def shortest_path(graph, source, target):
    # Initialize distances dictionary with infinity for all nodes except source
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize a set of processed nodes
    processed = set()

    # Function to find the unprocessed node with the smallest tentative distance
    def find_min_distance_node():
        min_distance = float('inf')
        min_node = None
        for node in distances:
            if node not in processed and distances[node] < min_distance:
                min_distance = distances[node]
                min_node = node
        return min_node

    # Function to update distances and paths based on the current node
    def update_distances_and_paths(node):
        for neighbor, weight in graph[node]:
            new_distance = distances[node] + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                path[neighbor] = path[node] + [neighbor]

