    queue_forward = [[source]]
    queue_backward = [[target]]
    visited_forward = {source}
    visited_backward = {target}

    # Bidirectional search variables
    distance_forward = {source: 0}
    distance_backward = {target: 0}

    # Forward search
    while queue_forward and queue_backward:
        # Forward search
        if queue_forward:
            current_forward = queue_forward.pop(0)
            current_forward_node = current_forward[-1]
            if current_forward_node == target:
                return distance_forward[target], current_forward

            if current_forward_node not in visited_forward:
                visited_forward[current_forward_node] = True
                for neighbor, weight in graph.get(current_forward_node, []):
