```python
import heapq

def heuristic(node, target):
    """Heuristic function (in this case, the Manhattan distance) used for A* Search."""
    return abs(node[0] - target[0]) + abs(node[1] - target[1])

def shortest_path(graph, source, target):
    # Priority queue to store (cost + heuristic, node, path)
    pq = [(0 + heuristic(source, target), source, [source])]
    # Set to keep track of visited nodes
    visited = set()

    while pq:
        current_cost, node, path = heapq.heappop(pq)

        if node == target:
            return (current_cost, path)

        if node not in visited:
            visited.add(node)

            for neighbor, weight in graph.get(node, []):
                new_cost = current_cost + weight
                new_path = path + [neighbor]

                if neighbor not in visited:
                    heapq.heappush(pq, (new_cost + heuristic(neighbor, target), neighbor, new_path))

    return (float("inf"), None)

# Example usage:
# Define a graph as a dictionary where each key is a node and the value is a list of (neighbor, weight) pairs.
