def shortest_path(graph, source, target):
    def relax(u, v, weight, dist, path):
        if dist[u] + weight < dist[v] and dist[u] != float('inf'):
            dist[v] = dist[u] + weight
            path[v] = u

    INF = float('inf')
    dist = {node: INF for node in graph}
    path = {node: None for node in graph}

    dist[source] = 0
    path[source] = None

    for _ in range(len(graph) - 1):
        for u in graph:
            for v, weight in graph[u]:
                relax(u, v, weight, dist, path)

    for u in graph:
