def shortest_path(graph, source, target):
    # Check if the target is reachable from the source
    def is_reachable(graph, source, target):
        visited = set([source])
        queue = deque([source])
        while queue:
            current = queue.popleft()
            for neighbor, _ in graph.get(current, []):
                if neighbor == target:
                    return True
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    # Helper function to perform topological sort
    def topological_sort(graph):
        indegree = {node: 0 for node in graph}
        for node in graph:
            for neighbor, _ in graph[node]:
                indegree[neighbor] += 1
        queue = deque([node for node in graph if indegree[node] == 0])
        sorted_nodes = []
        while queue:
            current_node = queue.popleft()
            sorted_nodes.append(current_node)
            for neighbor, _ in graph[current_node]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)
        return sorted_nodes

    # Perform topological sort on the graph
    sorted_nodes = topological_sort(graph)

    # Use Dijkstra's algorithm starting from the source
    if target not in sorted_nodes:
        return float("inf"), None

    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    path = {node: [] for node in graph}

    unvisited = deque(sorted_nodes)
    seen = set()
    seen.add(source)

    while unvisited:
        current = unvisited.popleft()
        seen.add(current)

        for neighbor, weight in graph[current]:
            if neighbor in seen:
                continue
            distance_through_current = distances[current] + weight
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                path[neighbor] = path[current] + [neighbor]
            if neighbor not in seen:
                unvisited.append(neighbor)

    return distances[target], path[target] if target in path else None

