    # Initialize the distance dictionary with infinity for all nodes except the source
    distances = {node: float('inf') for node in graph}
    distances[source] = 0  # Distance from source to itself is 0
    previous = {node: None for node in graph}  # Stores the previous node in the shortest path

    # Relax edges |V| - 1 times
    for _ in range(len(graph)):
