```python
def shortest_path(graph, source, target):
    # Initialize distances to all nodes as infinity and the distance to source as 0
    distances = {node: float("inf") for node in graph}
    distances[source] = 0

    # Initialize the parent dictionary to keep track of the path
    parents = {node: None for node in graph}

    # Relax edges |V| - 1 times
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    parents[neighbor] = node

    # Check for negative weight cycles
    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                raise ValueError("Graph contains a negative weight cycle")

    # Check if the target is reachable from the source
    if distances[target] == float("inf"):
        return float("inf"), None

    # Reconstruct the path
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = parents[current]

    return distances[target], path[::-1]

