import heapq

def heuristic(node, target):
    # Simple heuristic: Euclidean distance between nodes
    # Adjust this based on your graph's nature
    return abs(node[0] - target[0]) + abs(node[1] - target[1])

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return float("inf"), None

    open_list = []
    heapq.heappush(open_list, (0, source, [source]))
    came_from = {}
    cost_so_far = {}
    came_from[source] = None
    cost_so_far[source] = 0

    while open_list:
        _, current, path = heapq.heappop(open_list)

        if current == target:
            return cost_so_far[current], path

        for next_node, weight in graph[current]:
            new_cost = cost_so_far[current] + weight
            if next_node not in cost_so_far or new_cost < cost_so_far[next_node]:
                cost_so_far[next_node] = new_cost
                priority = new_cost + heuristic(next_node, target)
                heapq.heappush(open_list, (priority, next_node, path + [next_node]))
                came_from[next_node] = current

    return float("inf"), None

