    distances = {node: {neighbor: weight if (node, neighbor) in graph[node] else float("inf") 
                        for neighbor, weight in graph[node]} 
                 for node in graph}

    # Floyd-Warshall algorithm
    for k in graph:
        for i in graph:
            for j in graph:
                distances[i][j] = min(distances[i][j], distances[i][k] + distances[k][j])

