def shortest_path(graph, source, target):
    num_nodes = len(graph)

    # Initialize the distance matrix
    dist = [[float('inf')] * num_nodes for _ in range(num_nodes)]
    for i in range(num_nodes):
        dist[i][i] = 0  # Distance from node i to itself is 0
    for i, neighbors in enumerate(graph):
        for neighbor, weight in neighbors:
            dist[i][neighbor] = weight
            dist[neighbor][i] = weight  # Graph is undirected

    # Floyd-Warshall algorithm to compute shortest paths between all pairs of nodes
    for k in range(num_nodes):
        for i in range(num_nodes):
            for j in range(num_nodes):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Check if the target is reachable from the source
    if dist[source][target] == float('inf'):
        return float('inf'), None

    # Reconstruct the shortest path
    path = [target]
    while target != source:
        for i in range(num_nodes):
            if dist[target][i] < dist[target][path[-1]]:
                target = i
        path.append(target)
    path.reverse()

    return dist[source][target], path

