```python
def shortest_path(graph, source, target):
    # Ensure source and target are valid
    if source not in graph or target not in graph:
        return float("inf"), None

    # Initialize distances and parent array
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    parent = {node: None for node in graph}

    # Run Bellman-Ford algorithm
    for _ in range(len(graph)):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[neighbor] > distances[node] + weight:
                    distances[neighbor] = distances[node] + weight
                    parent[neighbor] = node

    # Check for negative weight cycles
    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[neighbor] > distances[node] + weight:
                # Negative weight cycle detected
                return float("inf"), None

    # Find the shortest path using DFS
    stack = [(target, [target])]
    while stack:
        current, path = stack.pop()
        if current == source:
            return distances[source], path
        for neighbor, _ in graph[current]:
            if neighbor not in parent or parent[neighbor] != current:
                stack.append((neighbor, path + [neighbor]))

    # If we reach here, no path exists
    return float("inf"), None

