Certainly! Johnson's Algorithm is a popular method for finding the shortest paths between all pairs of vertices in a weighted graph, even if the graph contains negative weight edges. It first removes negative weights using a pre-processing step and then uses Dijkstra's algorithm for the shortest path calculations.

Here is a complete implementation of the `shortest_path` function using Python:

```python
from collections import defaultdict
from heapq import heappop, heappush

def shortest_path(graph, source, target):
    def preprocess(graph):
        # Build a new graph with zero weights to remove negative weights
        zero_weight_graph = defaultdict(dict)
        for u, neighbors in graph.items():
            for v, weight in neighbors:
                zero_weight_graph[u][v] = 0
                zero_weight_graph[v][u] = 0

        # Use Bellman-Ford to compute shortest paths from source to all other nodes
        n = max(max(u, v) for u, v in (zero_weight_graph.keys() + zero_weight_graph.values()))
        distances = {u: float('inf') for u in range(n + 1)}
        distances[source] = 0
        for _ in range(n):
            for u in range(n + 1):
                if distances[u] != float('inf'):
                    for v in zero_weight_graph[u]:
                        if distances[u] + zero_weight_graph[u][v] < distances[v]:
                            distances[v] = distances[u] + zero_weight_graph[u][v]

        # Compute the actual shortest paths
        shortest_paths = {u: [] for u in range(n + 1)}
        for u in range(n + 1):
            for v in zero_weight_graph[u]:
                if distances[u] + zero_weight_graph[u][v] == distances[v]:
                    shortest_paths[v].append((u, v))

        # Convert the zero-weight graph to an actual graph
        actual_graph = defaultdict(dict)
        for u, neighbors in graph.items():
            for v, weight in neighbors:
                actual_graph[u][v] = weight
                if v in shortest_paths[u]:
                    actual_graph[u][v] += distances[u]

        return actual_graph

    def dijkstra(graph, start, end, n):
        # Priority queue to keep track of the nodes to visit
        pq = [(0, start, [])]
        visited = set()
        path = []

        while pq:
            (cost, u, path) = heappop(pq)
            if u not in visited:
                visited.add(u)
                path.append(u)
                if u == end:
                    return path, cost
                for v in graph[u]:
                    if v not in visited:
                        heappush(pq, (cost + graph[u][v], v, path[:]))
        return None, float('inf')

