from collections import defaultdict, deque
import heapq

def shortest_path(graph, source, target):
    # Check if the target is directly connected to the source
    if target in graph.get(source, []):
        return (0, [source, target])

    # Initialize the priority queue
    queue = deque([(0, [source])])
    visited = set()

    while queue:
        (distance, path) = queue.popleft()
        current = path[-1]

        if current == target:
            return (distance, path)

        if current not in visited:
            visited.add(current)
            for neighbour, weight in graph.get(current, []):
                if neighbour not in visited:
                    new_path = path + [neighbour]
                    heapq.heappush(queue, (distance + weight, new_path))

    return (float("inf"), None)

# Example usage
