```python
def shortest_path(graph, source, target):
    # Initialize distances and predecessors
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    predecessors = {node: None for node in graph}

    # PDDA algorithm
    while distances[target] == float('inf'):
        for current_node in graph:
            for neighbor, weight in graph[current_node]:
                distance_through_current_node = distances[current_node] + weight
                if distance_through_current_node < distances[neighbor]:
                    distances[neighbor] = distance_through_current_node
                    predecessors[neighbor] = current_node

        # Choose the unvisited node with the smallest distance
        next_node = min((node for node in graph if node not in distances or distances[node] == float('inf')), key=lambda node: distances[node])
        if next_node is None:
            return float('inf'), None

    # Reconstruct the path from source to target
    path = [target]
    while path[-1] != source:
        path.append(predecessors[path[-1]])
    path.reverse()

    return distances[target], path

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('C', 2), ('D', 5)],
    'C': [('D', 1)],
    'D': [('E', 1)],
    'E': []
}

print(shortest_path(graph, 'A', 'E'))  # Example: (4, ['A', 'B', 'C', 'D', 'E'])
print(shortest_path(graph, 'A', 'F'))  # Example: (float('inf'), None)
```

