```python
def shortest_path(graph, source, target):
    # Initialize the dictionaries for forward and backward searches
    forward = {source: [source]}
    backward = {target: [target]}

    # Initialize the dictionaries to store the shortest distance from source and target
    distances_forward = {source: 0}
    distances_backward = {target: 0}

    # Directions for moving forward and backward in the graph
    directions_forward = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    directions_backward = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    # Initialize the queue for forward and backward searches
    queue_forward = [source]
    queue_backward = [target]

    while queue_forward and queue_backward:
        # Process nodes from the front of the queues
        front = queue_forward.pop(0)
        back = queue_backward.pop(0)

        # Explore neighbors in the forward direction
        for delta_x, delta_y in directions_forward:
            next_node = (front[0] + delta_x, front[1] + delta_y)
            if next_node in graph:
                if next_node not in forward and next_node not in distances_forward:
                    forward[next_node] = forward[front][:]
                    forward[next_node].append(next_node)
                    distances_forward[next_node] = distances_forward[front] + graph[next_node][0][1]
                    queue_forward.append(next_node)

        # Explore neighbors in the backward direction
        for delta_x, delta_y in directions_backward:
            next_node = (back[0] + delta_x, back[1] + delta_y)
            if next_node in graph:
                if next_node not in backward and next_node not in distances_backward:
                    backward[next_node] = [next_node] + backward[back]
                    distances_backward[next_node] = distances_backward[back] + graph[next_node][0][1]
                    queue_backward.append(next_node)

        # Check if we have found a common node
        if any(node in backward and node in forward for node in distances_forward):
            # Find the common node
            common_node = [node for node in distances_forward if node in distances_backward and node in forward][0]

            # Calculate the total distance
            total_distance = distances_forward[common_node] + distances_backward[common_node]
            return (total_distance, forward[common_node] + backward[common_node][::-1])

    # If no path is found, return infinity and None
    return (float("inf"), None)

# Example usage:
# graph = {
#     (0, 0): [(1, 1), (2, 3)],
#     (1, 0): [(0, 0), (2, 2)],
#     (2, 0): [(0, 0), (1, 0), (3, 1)],
#     (3, 0): [(2, 0)]
# }
