    backward_queue = deque([(target, [target])])
    forward_visited = {source}
    backward_visited = {target}

    # Initialize the minimum distances to infinity
    forward_dist = {source: 0}
    backward_dist = {target: 0}

    # Bidirectional search loop
    while forward_queue and backward_queue:
        # Expand nodes from the front of their respective queues
        (current_forward, path_forward) = forward_queue.popleft()
        (current_backward, path_backward) = backward_queue.popleft()

        # If the nodes have been visited before, skip to next iteration
        if current_forward in forward_visited and current_forward not in forward_dist:
            continue
        if current_backward in backward_visited and current_backward not in backward_dist:
            continue

        # Update the minimum distance and path
        if current_forward == current_backward:
            # Found the shortest path
            path = path_forward[::-1] + path_backward
            return (forward_dist[current_forward], path)
        forward_visited.add(current_forward)
        backward_visited.add(current_backward)
        forward_dist[current_forward] = forward_dist.get(current_backward) + 1
        backward_dist[current_backward] = backward_dist.get(current_forward) + 1

