from collections import defaultdict
import heapq

def shortest_path(graph, source, target):
    # Initialize distances and path
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Initialize a priority queue for BFS
    priority_queue = [(0, source)]

    # Dictionary to keep track of the previous node in the shortest path
    previous = {node: None for node in graph}

    # Dictionary to store the actual path
    path = {}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we reach the target, reconstruct the path
        if current_node == target:
            reconstructed_path = []
            while current_node is not None:
                reconstructed_path.append(current_node)
                current_node = previous[current_node]
            return (current_distance, list(reversed(reconstructed_path)))

        # Skip if we've already found a shorter path to this node
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Only consider this new path if it's shorter
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                # Add the neighbor to the priority queue with the distance as the priority
                heapq.heappush(priority_queue, (distance, neighbor))

    # If the target is unreachable, return infinity and None
    return (float('inf'), None)

# Example usage:
graph_example = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

print(shortest_path(graph_example, 'A', 'D'))  # Example output: (6, ['A', 'C', 'D'])
```

