```python
def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return float("inf"), None

    # Initialize the distance dictionary
    distance = {node: float("inf") for node in graph}
    distance[source] = 0

    # Relax edges |V|-1 times
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distance[node] + weight < distance[neighbor]:
                    distance[neighbor] = distance[node] + weight

    # Check for negative-weight cycles
    for node in graph:
        for neighbor, weight in graph[node]:
            if distance[node] + weight < distance[neighbor]:
                return float("inf"), None

    # Construct the path from the distance dictionary
    path = []
    current_node = target
    while current_node != source:
        for neighbor, weight in graph[current_node]:
            if distance[current_node] == distance[neighbor] + weight:
                path.append(current_node)
                current_node = neighbor
                break
    path.append(source)
    path.reverse()

    return distance[target], path

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

source = 'A'
target = 'D'
distance, path = shortest_path(graph, source, target)
print(f"Shortest Distance: {distance}")
print(f"Path: {path}")
