def shortest_path(graph, source, target):
    # Initialize distances and predecessor array
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    predecessors = {node: None for node in graph}

    # Relax edges |V| - 1 times
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessors[neighbor] = node

    # Check for negative-weight cycles
    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                raise ValueError("Graph contains a negative-weight cycle")

    # Construct the shortest path from target to source
    path = []
    current = target
    while current is not None:
        path.append(current)
        if predecessors[current] is None:
            break
        current = predecessors[current]

    # If the path is not found, return infinity and None
    if path[-1] != source:
        return float('inf'), None
    else:
        path.reverse()
        return distances[target], path

# Example usage:
graph = {
    'A': [('B', 2), ('C', 5)],
    'B': [('A', 2), ('C', 1), ('D', 4)],
    'C': [('A', 5), ('B', 1), ('D', 3)],
    'D': [('B', 4), ('C', 3)]
}

source = 'A'
target = 'D'
distance, path = shortest_path(graph, source, target)
print(f"Shortest distance from {source} to {target}: {distance}")
print(f"Shortest path from {source} to {target}: {path}")
```

