    graph = {
        'A': [('B', 1), ('C', 4)],
        'B': [('A', 1), ('C', 2), ('D', 5)],
        'C': [('A', 4), ('B', 2), ('D', 1)],
        'D': [('B', 5), ('C', 1)]
    }
    source = 'A'
    target = 'D'
    shortest_path_distance, shortest_path = shortest_path(graph, source, target)
    print(f"Shortest path from {source} to {target} is {shortest_path_distance} with path {shortest_path}")
