def shortest_path(graph, source, target):
    # A* Search Algorithm implementation
    def heuristic(node):
        # Simple heuristic: distance to target node
        return 0 if node == target else float('inf')

    open_set = [(0, source, [])]
    came_from = {}
    cost_so_far = {source: 0}
    found_path = False

    while open_set:
        # Sort by cost, then by node name (alphabetically)
        open_set.sort(key=lambda x: (x[0], x[1]))
        _, current = heappop(open_set)

        if current == target:
            found_path = True
            break

        for neighbor, weight in graph.get(current, []):
            new_cost = cost_so_far[current] + weight
            if neighbor not in cost_so_far or new_cost < cost_so_far[neighbor]:
                cost_so_far[neighbor] = new_cost
                priority = new_cost + heuristic(neighbor)
                heappush(open_set, (priority, neighbor, current + [neighbor]))
                came_from[neighbor] = current

        if found_path:
            break

    if found_path:
        # Reconstruct the path
        path = []
        current = target
        while current:
            path.insert(0, current)
            current = came_from.get(current)
        return (cost_so_far[target], path)
    else:
        return (float('inf'), None)

