def shortest_path(graph, source, target):
    # Initialize the distance dictionary
    # Initially, we assume the distance from source to itself is 0 and to all other nodes is infinity
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Initialize the previous node dictionary for the path reconstruction
    previous_nodes = {node: None for node in graph}

    # Priority queue for BFS, initially containing the source node
    from collections import deque
    queue = deque([source])

    while queue:
        current_node = queue.popleft()

        # If we reached the target, we can reconstruct the path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous_nodes[current_node]
            path.reverse()
            return (distances[target], path)

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance_through_current_node = distances[current_node] + weight

            # If a shorter path is found, update the distance and previous node
            if distance_through_current_node < distances[neighbor]:
                distances[neighbor] = distance_through_current_node
                previous_nodes[neighbor] = current_node
                queue.append(neighbor)

    # If target is unreachable, return infinity for distance and None for path
    return (float('inf'), None)
