Certainly! Below is a Python implementation of a new shortest path algorithm that finds the shortest path in a weighted graph, specifically using Dijkstra's algorithm. This implementation includes a function `shortest_path(graph, source, target)` that returns a tuple `(distance, path)` with `path` being a list of nodes from the `source` to the `target`, and `distance` being the weight of the shortest path.

```python
import heapq

def shortest_path(graph, source, target):
    # Helper function to return the path given the shortest distances
    def reconstruct_path(predecessors, target):
        path = []
        while target:
            path.append(target)
            target = predecessors[target]
        return path[::-1]

    # Priority queue to store (distance, node) tuples
    pq = [(0, source)]
    # Dictionary to store the shortest distance from the source to each node
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    # Dictionary to store the predecessor of each node
    predecessors = {node: None for node in graph}

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        if current_node == target:
            return (distances[target], reconstruct_path(predecessors, target))

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    # If target is unreachable, return infinity and None
    return (float('inf'), None)

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

source = 'A'
target = 'D'
print(shortest_path(graph, source, target))  # Output: (6, ['A', 'C', 'D'])
```

