def shortest_path(graph, source, target):
    # Initialize distances and parents
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    parents = {node: None for node in graph}

    # Priority queue to manage nodes to visit
    queue = [(0, source)]
    visited = set()

    while queue:
        current_distance, current_node = queue.pop(0)
        visited.add(current_node)

        # No need to explore this node further if we've already found a shorter path to it
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                parents[neighbor] = current_node
                # Add to queue with current distance
                queue.append((distance, neighbor))

        # If we've visited all nodes, we can exit early
        if all(distances[node] != float('inf') for node in graph):
            break

    # Construct the path if it exists, otherwise return infinity and None
    if parents[target] is None:
        return float('inf'), None
    else:
        path = []
        node = target
        while node is not None:
            path.insert(0, node)
            node = parents[node]
        return distances[target], path
