from heapq import heappush, heappop

def shortest_path(graph, source, target):
    # Implementing the A* Search Algorithm with a custom heuristic

    open_set = []
    heappush(open_set, (0, source, [source]))

    while open_set:
        # Pop the node with the lowest f-score
        _, current, path = heappop(open_set)

        # If we have reached the target node, return the path and the cost
        if current == target:
            return (len(path) - 1, path)

        # Mark the node as visited
        visited.add(current)

        # Explore each neighbor
        for neighbor, weight in graph.get(current, []):
            if neighbor not in visited:
                # Calculate tentative distance to neighbor through current node
                tentative_distance = len(path) + weight
                # Calculate the heuristic: using the average length of all edges as the heuristic function
                heuristic = sum(graph[node] for node in graph if node in path).average() / len(path)
                # Calculate f-score
                f_score = tentative_distance + heuristic

                # If we have not visited the neighbor or found a better path, add it to the open set
                if neighbor not in [n for _, _, n in open_set] or f_score < open_set[0][0]:
                    heappush(open_set, (f_score, neighbor, path + [neighbor]))

    # If we exhaust the open set without finding the target, return unreachable
    return (float("inf"), None)

# Helper function to calculate the average length of all edges
class Graph:
    def __init__(self, edges):
        self.graph = {node: [] for node in edges}
        for node1, node2, weight in edges:
            self.graph[node1].append((node2, weight))
            self.graph[node2].append((node1, weight))

    def average(self):
        total_weight = sum(weight for node in self.graph.values() for _, weight in node)
        return total_weight / len(self.graph)

# Example usage:
graph = Graph([("A", "B", 1), ("A", "C", 4), ("B", "C", 2), ("B", "D", 5), ("C", "D", 1)])
print(shortest_path(graph, "A", "D"))  # Example output: (3, ['A', 'B', 'C', 'D'])
```

