from collections import defaultdict
from heapq import heappop, heappush
from typing import Dict, List, Tuple

def shortest_path(graph: Dict[str, List[Tuple[str, int]]], source: str, target: str) -> Tuple[float, List[str]]:
    # Kruskal's Algorithm for Minimum Spanning Tree (MST) does not directly solve shortest path problem
    # We will use Dijkstra's algorithm instead to find the shortest path from source to target
    def dijkstra(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]

        while queue:
            current_distance, current_node = heappop(queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph.get(current_node, []):
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heappush(queue, (distance, neighbor))

        return distances[target]

    return (dijkstra(graph, source), [node for node, _ in dijkstra(graph, source).items() if node == target])

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('A', 1), ('C', 2), ('D', 5)],
    'C': [('A', 4), ('B', 2), ('D', 1)],
    'D': [('B', 5), ('C', 1)]
}

source = 'A'
target = 'D'
print(shortest_path(graph, source, target))
```

