from heapq import heappush, heappop

def shortest_path(graph, source, target):
    # Initialize the distance dictionary
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Initialize the priority queue with the source node
    priority_queue = []
    heappush(priority_queue, (0, source))

    # Dictionary to store the previous node for the shortest path
    previous = {}

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # Check if we've reached the target
        if current_node == target:
            path = []
            while current_node in previous:
                path.append(current_node)
                current_node = previous[current_node]
            path.append(source)
            path.reverse()
            return (current_distance, path)

        # If the node is not the source and the distance is greater than the known distance, skip
        if current_node != source and current_distance > distances[current_node]:
            continue

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            # Only consider this new path if it's shorter
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                heappush(priority_queue, (distance, neighbor))

    # If we can't reach the target, return infinity and None
    return (float('inf'), None)
