import heapq

def shortest_path(graph, source, target):
    # Initialize the distance dictionary with infinity for all nodes except the source
    distance = {node: float('inf') for node in graph}
    distance[source] = 0

    # Priority queue to store tuples (distance, node)
    pq = [(0, source)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        # If we reach the target node, we can stop since we only push one path per node
        if current_node == target:
            return (current_distance, [target])

        # Skip nodes that have been already processed
        if current_distance > distance[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance_to_neighbor = current_distance + weight

            # If we find a shorter path to the neighbor, update the distance and push to the priority queue
            if distance_to_neighbor < distance[neighbor]:
                distance[neighbor] = distance_to_neighbor
                heapq.heappush(pq, (distance_to_neighbor, neighbor))

    # If target is unreachable, return infinity and None
    if distance[target] == float('inf'):
        return (float('inf'), None)
    else:
        return (distance[target], [target])

# Example usage:
graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('C', 1), ('D', 4)],
    'C': [('D', 1)],
    'D': [('C', 1)]
}

