def shortest_path(graph, source, target):
    # Create a dictionary to cache shortest path lengths
    shortest_paths = {source: (0, [source])}

    def dijkstra(graph, source):
        # Priority queue to store (distance, node)
        queue = [(0, source)]
        while queue:
            curr_distance, curr_node = heappop(queue)
            if curr_node == target:
                return curr_distance, shortest_paths[curr_node][1]  # target found
            if curr_distance > shortest_paths[curr_node][0]:
