from collections import deque
import heapq

def shortest_path(graph, source, target):
    # Step 1: Transform the graph to convert all negative weights to non-negative
    def transform_and_add_self_loops(graph):
        # Use a temporary graph to avoid altering the original graph
        temp_graph = {node: [] for node in graph}

        # Add self-loop edges with infinite weight to convert negative weights to non-negative
        for node, neighbors in graph.items():
            for neighbor, weight in neighbors:
                temp_graph[node].append((neighbor, weight + float('inf')))
            temp_graph[node].append((node, float('inf')))

        # Transform the graph using Johnson's algorithm
        for node in graph:
            for neighbor, weight in temp_graph[node]:
                if neighbor in graph and (neighbor, weight) not in graph[node]:
                    graph[node].append((neighbor, weight))

        return temp_graph

    # Step 2: Initialize Dijkstra's algorithm
    def dijkstra(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return distances

    # Step 3: Run the transformation and Dijkstra's algorithm
    transformed_graph = transform_and_add_self_loops(graph)
    distances = dijkstra(transformed_graph, source)

    # Step 4: Reconstruct the shortest path
    if distances[target] == float('inf'):
        return (float('inf'), None)

    path = []
    node = target
    while node != source:
        path.append(node)
        for neighbor, _ in transformed_graph[node]:
            if distances[neighbor] == distances[node] - transformed_graph[node][0][1]:
                node = neighbor
                break
    path.append(source)
    path.reverse()

    return (distances[target], path)

# Example usage:
