    'A': [('B', 2), ('C', 4)],
    'B': [('C', 1), ('D', 3)],
    'C': [('D', 1)],
    'D': [('C', 2)],
}

print(shortest_path(graph, 'A', 'D'))  # Output should be (4, ['A', 'B', 'D'])
