    def relax(node, neighbor, weight, dist, path):
        if dist[neighbor] > dist[node] + weight:
            dist[neighbor] = dist[node] + weight
            path[neighbor] = path[node] + [neighbor]

    # Dijkstra's algorithm
    dist = defaultdict(lambda: float('inf'))
